@using sv_3be9d729ee684236a0f97c8ab2218206.Models

<nav class="step-indicator" aria-label="Application steps">
    <ol>
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var css = step == CurrentStep ? "step active"
                    : step < CurrentStep ? "step completed"
                    : "step future";

            <li class="@css"
                @onclick="() => OnStepClick(step)"
                role="button"
                tabindex="@(step < CurrentStep ? 0 : -1)"
                aria-current="@(step == CurrentStep ? "step" : null)">
                <span class="step-number">
                    @if (step < CurrentStep)
                    {
                        <span aria-hidden="true">&#10003;</span>
                    }
                    else
                    {
                        @(step + 1)
                    }
                </span>
                <span class="step-label">@StepNames[step]</span>
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter]
    public EventCallback<int> OnStepSelected { get; set; }

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
        {
            await OnStepSelected.InvokeAsync(step);
        }
    }
}

@using sv_3be9d729ee684236a0f97c8ab2218206.Models

<div class="work-entry-editor">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" class="form-control" @bind="Entry.Company" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" class="form-control" @bind="Entry.Title" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" @bind="Entry.StartDate" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" @bind="Entry.EndDate" disabled="@Entry.IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" @bind="Entry.IsCurrent" @bind:after="OnCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" @bind="Entry.Description"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public WorkEntryModel Entry { get; set; } = default!;

    [Parameter]
    public int Index { get; set; }

    [Parameter]
    public bool ShowRemove { get; set; }

    [Parameter]
    public EventCallback OnRemove { get; set; }

    private void OnCurrentChanged()
    {
        if (Entry.IsCurrent)
        {
            Entry.EndDate = null;
        }
    }
}

@using sv_3be9d729ee684236a0f97c8ab2218206.Models

<div class="step-panel">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" class="form-control" @bind="Model.FullName" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" class="form-control" @bind="Model.Email" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" class="form-control" @bind="Model.Phone" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea class="form-control" rows="2" @bind="Model.Address"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="step-buttons">
        <span></span>
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating…" : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public PersonalInfoModel Model { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback OnNext { get; set; }

    [Parameter, EditorRequired]
    public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName))
        { ErrorMessage = "Full name is required."; return; }

        if (string.IsNullOrWhiteSpace(Model.Email))
        { ErrorMessage = "Email is required."; return; }

        if (string.IsNullOrWhiteSpace(Model.Phone))
        { ErrorMessage = "Phone is required."; return; }

        if (string.IsNullOrWhiteSpace(Model.Address))
        { ErrorMessage = "Address is required."; return; }

        IsValidating = true;
        try
        {
            var valid = await ValidateEmail(Model.Email);
            if (!valid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_3be9d729ee684236a0f97c8ab2218206.Models

<div class="step-panel">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryEditor Entry="Entries[index]"
                         Index="index"
                         ShowRemove="Entries.Count > 1"
                         OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-outline-primary" @onclick="AddEntry">
        + Add Another Position
    </button>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<WorkEntryModel> Entries { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback OnNext { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) ||
                string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate is null)
            {
                ErrorMessage = "Each position requires a company name, job title, and start date.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_3be9d729ee684236a0f97c8ab2218206.Models

<div class="step-panel">
    <h3>References</h3>
    <p class="hint">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceEditor Reference="References[index]"
                         Index="index"
                         ShowRemove="References.Count > 2"
                         OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-outline-primary" @onclick="AddReference">
            + Add Reference
        </button>
    }

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="validation-error">@ErrorMessage</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<ReferenceModel> References { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback OnNext { get; set; }

    [Parameter, EditorRequired]
    public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (References.Count < 2)
        {
            ErrorMessage = "At least 2 references are required.";
            return;
        }

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) ||
                string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference requires a name, relationship, and email.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_3be9d729ee684236a0f97c8ab2218206.Models

<div class="step-panel review-panel">
    <h3>Review &amp; Submit</h3>

    @if (Submitted)
    {
        <div class="confirmation">
            <h4>✓ Application Submitted!</h4>
            <p>Your application has been received. Your application ID is <strong>@ApplicationId</strong>.</p>
        </div>
    }
    else
    {
        <section class="review-section">
            <div class="review-header">
                <h4>Personal Information</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
            </div>
            <dl>
                <dt>Name</dt><dd>@Personal.FullName</dd>
                <dt>Email</dt><dd>@Personal.Email</dd>
                <dt>Phone</dt><dd>@Personal.Phone</dd>
                <dt>Address</dt><dd>@Personal.Address</dd>
            </dl>
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>Work History</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-work-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <span class="date-range">
                        @entry.StartDate?.ToString("MMM yyyy")
                        –
                        @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                    </span>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </section>

        <section class="review-section">
            <div class="review-header">
                <h4>References</h4>
                <button type="button" class="btn-link" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            @foreach (var r in References)
            {
                <div class="review-reference">
                    <strong>@r.Name</strong> — @r.Relationship
