}

.step.active .step-number {
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-number {
    background: #198754;
    color: #fff;
    cursor: pointer;
}

.step.future .step-number {
    background: #e9ecef;
    color: #adb5bd;
}

.step-label {
    margin-top: 0.35rem;
    font-size: 0.75rem;
    color: #6c757d;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.completed {
    cursor: pointer;
}

/* Step Panels */
.step-panel {
    background: #fff;
