    border-bottom: 1px solid #eee;
    padding-bottom: 0.75rem;
}

/* Form Layout */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.9rem;
}

.form-control {
    width: 100%;
