}

.btn-outline-danger:hover {
    background: #dc3545;
    color: #fff;
}

.btn-sm {
    padding: 0.25rem 0.75rem;
    font-size: 0.8rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    padding: 0;
    text-decoration: underline;
}

.btn-link:hover {
    color: #0a58ca;
}

.step-buttons {
    display: flex;
    justify-content: space-between;
