/* Validation */
.validation-error {
    background: #f8d7da;
    color: #842029;
    padding: 0.65rem 1rem;
    border-radius: 0.375rem;
    margin-top: 1rem;
    font-size: 0.9rem;
}

/* Work Entry / Reference Editors */
.work-entry-editor,
.reference-editor {
    border: 1px solid #e9ecef;
    border-radius: 0.375rem;
    padding: 1rem;
    margin-bottom: 1rem;
    background: #fafbfc;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.entry-header h4,
.reference-editor h4 {
    margin: 0;
    font-size: 1rem;
}

.reference-editor {
    position: relative;
}

.remove-ref {
    position: absolute;
    top: 1rem;
    right: 1rem;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 180px;
}

.char-count {
    text-align: right;
    font-size: 0.8rem;
    color: #6c757d;
    margin-top: 0.25rem;
}

.char-count.over-limit {
    color: #dc3545;
    font-weight: 600;
}

.hint {
    color: #6c757d;
    font-size: 0.9rem;
    margin-bottom: 1rem;
}

/* Review Step */
.review-section {
    margin-bottom: 1.25rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #eee;
}

.review-section:last-of-type {
    border-bottom: none;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.review-header h4 {
    margin: 0;
}

.review-section dl {
    display: grid;
    grid-template-columns: 8rem 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 500;
    color: #6c757d;
}

.review-work-entry,
.review-reference {
    margin-bottom: 0.75rem;
    padding: 0.5rem 0;
}

.date-range {
    font-size: 0.85rem;
    color: #6c757d;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 0.375rem;
    font-size: 0.9rem;
}

.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h4 {
    color: #198754;
    font-size: 1.5rem;
    margin-bottom: 1rem;
}

